import{z as o,x as d,o as E,c as p,q as i,j as B,D as n,d as r,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"保证金与维持保证金","description":"","frontmatter":{"title":"保证金与维持保证金","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/margin-maintenance.md","filePath":"quant/margin-maintenance.md","lastUpdated":1791413859000}'),A={name:"quant/margin-maintenance.md"};function D(m,a,u,h,f,T){const t=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=i('<h1 id="保证金与维持保证金" tabindex="-1">保证金与维持保证金 <a class="header-anchor" href="#保证金与维持保证金" aria-label="Permalink to &quot;保证金与维持保证金&quot;">​</a></h1><div class="epigraph"><p>报表杠杆是会计身份；保证金是经纪商按持仓与规则锁住的现金。回测若只乘杠杆倍数、不设维持线，等于假设资金无限且不会被要求追加。</p><footer>—— 据 Reg T / FINRA 维持保证金惯例；Brunnermeier and Pedersen, Review of Financial Studies, 2009 对融资流动性整理</footer></div><p>上一课<a href="/quant/nci-consolidation">合并与少数股东</a>收束了公司状态表。本课是「市场制度、资金与事件」第一课；后课默认你已区分<strong>报表杠杆</strong>与<strong>可交易保证金</strong>。缺口从「当时能读到什么基本面」换成「当时能加多少杠杆、保证金何时被催缴」。不重写 NCI，不把强平路径提前讲完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基本面多空组合在研究里常按市值加权再乘一个名义杠杆。真实账户要缴初始保证金，价格逆向移动后要满足维持保证金，否则被要求追加或减仓。Brunnermeier–Pedersen 把市场流动性与融资流动性绑在一起：价格下跌抬升保证金、迫使卖出、再压价格。缺口是把这条约束写进回测状态机，而不是把杠杆当常数。</p><p><span class="marginnote">翻译成白话：初始保证金像租房押金，开仓时先锁住；维持保证金像「押金不能低于某个数」的条款——亏损把押金吃掉、跌破这条线，经纪商就催你补交，补不上就请你减仓离场。</span></p><p>财务课的资产负债率不能映射成保证金率。经纪商看的是持仓类别、集中度、是否可融资，不是合并报表的 D/E。</p><h3 id="初始保证金不是维持保证金" tabindex="-1">初始保证金不是维持保证金 <a class="header-anchor" href="#初始保证金不是维持保证金" aria-label="Permalink to &quot;初始保证金不是维持保证金&quot;">​</a></h3><p>开仓按初始比例锁现金；持仓期间按维持比例检查。价格有利时，超额保证金可被抽走去开新仓；价格不利时，先碰到维持线而不是初始线。回测若只用初始比例做杠杆上限，会低估追保频率。后课强平是维持线被击穿且未能追加之后的路径。</p><p><span class="marginnote">Reg T 对美股多头初始常见 50%、维持 25% 量级，但组合保证金、指数期货、融券空头各不相同。本课要的是双线结构，不是某一司法辖区的法条表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>账户状态至少含：现金、持仓市值、已用保证金、可提取超额。每日（或每次标记）计算保证金占用，与维持要求比较。信号给出的目标仓位若使初始保证金不足，必须降杠杆或拒绝开仓，而不是按无约束权重成交。形成日宇宙仍用财务课的 PIT 与退市规则；本课只叠加资金约束。</p><p>回测要声明是隔夜保证金还是盘中最高占用。用收盘价检查维持线，会漏掉盘中击穿——这是后课缺口风险的入口，本课先承认检查频率是模型的一部分。</p>',13)),(E(),B(s,null,{default:n(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%97%A0%E7%BA%A6%E6%9D%9F%E7%9B%AE%E6%A0%87%E4%BB%93%E4%BD%8D%22%5D%20--%3E%20INIT%5B%22%E5%88%9D%E5%A7%8B%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20INIT%20--%3E%20POS%5B%22%E5%8F%AF%E5%BC%80%E4%BB%93%E4%BD%8D%22%5D%0A%20%20POS%20--%3E%20MTN%5B%22%E7%BB%B4%E6%8C%81%E4%BF%9D%E8%AF%81%E9%87%91%E6%A3%80%E6%9F%A5%22%5D%0A%20%20MTN%20--%3E%20OK%5B%22%E7%BB%A7%E7%BB%AD%E6%8C%81%E6%9C%89%22%5D%0A%20%20MTN%20--%3E%20CALL%5B%22%E8%BF%BD%E4%BF%9D%E6%88%96%E5%87%8F%E4%BB%93%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"纸面目标权重可保留，可交易仓位必须经初始线裁剪、维持线检查。全样本常数杠杆倍数从本课起视为非法默认。危机月并排报告有无维持线的净值差。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"保证金把策略的「理论 alpha」变成受资金约束的路径依赖。同一信号在波动上升时占用变大，能承载的名义下降，于是因子在最需要承担风险的时候被迫减杠杆——这是回测偏差：无约束回测在危机里仍满仓，实盘已经撞维持线。财务质量空头往往是高波动、难融资的名字，保证金约束会非对称地砍空头。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"后课把资金成本当作 alpha 底。本课先把占用与维持线变成状态变量；没有占用，成本无处乘。")],-1)),a[7]||(a[7]=e("p",null,"最低实现：每个账户日终记录市值、现金、初始占用、维持要求。目标仓位先按初始线裁剪，再在日终按维持线检查；不足则按规则减仓，而不是按信号权重成交。杠杆上限随波动与集中度变化，不得在全样本用同一个 2 倍乘数。危机月把无约束回测与有维持线回测并排，差额就是资金前视的尺度。盘中检查缺失要在文档里写明，作为后课缺口的已知漏洞。",-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"数字示例：100 万现金按 50% 初始保证金持有 200 万仓位（2 倍杠杆）。股价跌 10%，权益剩 80 万、仓位 180 万，保证金占比约 44%，安全；跌 25%，权益 50 万、仓位 150 万，占比约 33%；数学上跌到约 33% 时占比恰触 25% 维持线——两倍杠杆把三分之一的跌幅变成追保电话。")],-1)),(E(),B(s,null,{default:n(()=>[l(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20PD%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%20--%3E%20EQ%5B%22%E6%9D%83%E7%9B%8A%E7%BC%A9%E6%B0%B4%22%5D%0A%20%20EQ%20--%3E%20BR%5B%22%E9%80%BC%E8%BF%91%E7%BB%B4%E6%8C%81%E7%BA%BF%22%5D%0A%20%20BR%20--%3E%20MC%5B%22%E8%BF%BD%E5%8A%A0%E4%BF%9D%E8%AF%81%E9%87%91%E6%88%96%E5%87%8F%E4%BB%93%22%5D%0A%20%20MC%20--%3E%20FS%5B%22%E8%A2%AB%E8%BF%AB%E5%8D%96%E5%87%BA%E5%8E%8B%E4%BD%8E%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20FS%20--%3E%20PD%0A%20%20VOL%5B%22%E6%B3%A2%E5%8A%A8%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20IM%5B%22%E5%88%9D%E5%A7%8B%E5%8D%A0%E7%94%A8%E6%8A%AC%E5%8D%87%22%5D%0A%20%20IM%20--%3E%20LEV%5B%22%E6%96%B0%E4%BB%93%E6%89%BF%E8%BD%BD%E8%83%BD%E5%8A%9B%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=i('<p><span class="marginnote">常见误区：以为「资产负债率低就安全」。经纪商看的不是合并报表的 D/E，而是每个账户的持仓类别、集中度与可融资性——财务上稳健的组合，照样可能因为单一持仓集中而被大幅抬高保证金占用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不汇编各国保证金法条，不写投资组合保证金的内部模型。下一课<a href="/quant/liquidation-gap-risk">强平与缺口风险</a>处理维持线以下、跳空无法追加的情形。融券机制与借券费率再后两课。后课默认：仓位先过初始保证金、再过维持线；无约束权重可留作纸面目标，但不是可交易仓位。集中度与波动使占用上升时，先降杠杆再谈再平衡，不要一边维持线已破一边还按信号加仓。日终检查漏掉的盘中击穿，记为模型已知漏洞，而不是用收盘价把路径抹平。</p><p>组合保证金与单票保证金不同：相关性上升时占用突然变大，常数单票比例会低估追保。回测若只用单票 50%/25%，要在文档里承认这是对组合规则的低估，而不是「已经很保守」。股票维持现金与期货 IM 通常分户，不可默认互相抵用。这是后课 CCP 占用与本课股票维持线并列、不能轧成一笔现金的原因。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报表杠杆 ≠ 保证金；本课程从资金约束起笔。</li><li>初始线管开仓，维持线管存续，两者不是同一个比例。</li><li>无约束因子回测在危机里满仓，是资金前视。</li><li>检查频率（收盘 vs 盘中）属于模型，会漏击穿。</li><li>后课强平、融券、回购都建立在这条状态机上。</li><li>出处：Reg T / FINRA 维持惯例；Brunnermeier and Pedersen (2009)。</li></ul>',6))])}const C=o(A,[["render",D]]);export{g as __pageData,C as default};
